use super::*;use super::super::component::Probe;
#[test]fn fixture_tasks_have_disjoint_writes_and_initialized_reads(){use std::collections::BTreeSet;let p=Probe::new(4,true,true,true);let mut all_writes=BTreeSet::new();let mut rows=BTreeSet::new();let mut reads=Vec::new();for task in &p.tasks{let mut own=BTreeSet::new();for code in task{let id=(code&INDEX)as usize;let op=&p.plan.ops[id];let Op::Constraint(step)=op else{panic!("fixture constraint expected")};assert!(rows.insert(step.constraint()));let mut current=BTreeSet::new();if let Some(a)=&step.assignment{assert!(current.insert(a.wire()));}let mut slot=p.plan.n_wires+step.first_slot();for sum in &p.plan.sums[step.sums()]{if sum.stored(){assert!(current.insert(slot));slot+=1;}}p.plan.reads(op,&mut reads);for read in &reads{assert!(*read<p.plan.n_inputs||own.contains(read)||(*read>=p.plan.n_wires&&current.contains(read)),"uninitialized read {read}");}for write in current{assert!(write>=p.plan.n_inputs&&write<p.w.len());assert!(all_writes.insert(write),"overlapping write {write}");own.insert(write);}}}assert_eq!(rows.len(),p.plan.n_constraints);}
#[test]fn parallel_modes_match_every_buffer_at_real_worker_counts(){
 for workers in [1,4,16,32]{let pool=rayon::ThreadPoolBuilder::new().num_threads(workers).build().unwrap();for groups in [1,4,16]{for reverse in [false,true]{for c in [false,true]{for ragged in [false,true]{let mut p=Probe::new(groups,reverse,c,ragged);p.reset(19);p.run(2).unwrap();let expected=p.snapshot();for mode in 0..=2{p.reset(19);p.arrange(mode==2,workers);pool.install(||p.parallel(mode)).unwrap();assert_eq!(p.snapshot(),expected,"workers={workers} groups={groups} reverse={reverse} C={c} ragged={ragged} mode={mode}");}}}}}}
}
#[test]fn grouping_moves_descriptors_only_and_reduces_ragged_tails(){let mut p=Probe::new(16,false,false,true);let image=p.plan.image();let original_ids:Vec<_>=p.tasks.iter().map(|t|t[0]&INDEX).collect();let plain=p.layout_counts(true);assert_eq!(plain,[255,128,127]);p.arrange(true,32);assert!(p.grouping_enabled());assert_eq!(p.plan.image(),image);assert_eq!(p.layout_counts(true),[255,248,7]);p.arrange(false,32);assert_eq!(p.tasks.iter().map(|t|t[0]&INDEX).collect::<Vec<_>>(),original_ids);for groups in [1,4]{let mut p=Probe::new(groups,false,false,true);p.arrange(true,16);assert!(!p.grouping_enabled());}}
#[test]fn parallel_untagged_and_other_widths_preserve_scalar_execution(){let pool=rayon::ThreadPoolBuilder::new().num_threads(4).build().unwrap();for width in [3,4,13]{let mut p=Probe::with_width(4,true,true,true,width);p.reset(7);p.run(2).unwrap();let expected=p.snapshot();for code in &mut p.tasks[0]{*code&=INDEX;}for mode in 0..=2{p.reset(7);p.arrange(mode==2,4);pool.install(||p.parallel(mode)).unwrap();assert_eq!(p.snapshot(),expected,"width={width} mode={mode}");}}}
